WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pb_ct_pc'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '排列组合求概率', 'kp-pb-ct-pc', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "排列组合求概率"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "分母是裸的 C 或 A；分子是加了限制条件的 C 或 A。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“从 3 男 4 女中挑 3 个人，恰好是 2 男 1 女的概率？”。这实质上是一道排列组合题。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "P = \\frac{\\text{条件排列组合数 (分步/分类/插空/捆绑)}}{\\text{总排列组合数 (无视条件盲抓)}}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 3男4女选3人，求恰好2男1女的概率？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算分母（随便挑3人）：C(7,3) = 35。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "算分子（满足2男1女）：先挑2男 C(3,2)=3，再挑1女 C(4,1)=4。分步相乘，分子 = 3×4 = 12。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "出结果：P = 12 / 35。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "分子分母顺序错乱：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "如果分子用了排列（A，考虑了顺序），分母也必须用排列（A）！如果分子用了组合（C，不考虑顺序），分母也必须用组合（C）！绝不能上面排座，下面瞎抓。"}]}]}]}$$ AS jsonb), NULL, '排列组合求概率的核心考点与实战推导。', category_node.id, CAST('["数量关系", "概率问题", "排列组合求概率"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pb_ct_pc", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
